#include <libavformat/avformat.h>
#include <libavutil/time.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){if(argc!=5)return 2;av_log_set_level(AV_LOG_ERROR);int64_t begin=av_gettime_relative();AVFormatContext*in=NULL,*out=NULL;AVPacket*p=av_packet_alloc();if(avformat_open_input(&in,argv[1],NULL,NULL)<0||avformat_find_stream_info(in,NULL)<0)return 3;int v=av_find_best_stream(in,AVMEDIA_TYPE_VIDEO,-1,-1,NULL,0);if(v<0)return 4;AVStream*is=in->streams[v];double target=atof(argv[2]);int count=atoi(argv[3]);if(av_seek_frame(in,v,(int64_t)(target/av_q2d(is->time_base)),AVSEEK_FLAG_BACKWARD)<0)return 5;avformat_alloc_output_context2(&out,NULL,"mp4",NULL);out->avoid_negative_ts=AVFMT_AVOID_NEG_TS_DISABLED;AVStream*os=avformat_new_stream(out,NULL);avcodec_parameters_copy(os->codecpar,is->codecpar);os->codecpar->codec_tag=0;os->time_base=is->time_base;if(avio_open_dyn_buf(&out->pb)<0)return 6;AVDictionary*opts=NULL;av_dict_set(&opts,"movflags","frag_keyframe+empty_moov+default_base_moof",0);if(avformat_write_header(out,&opts)<0)return 7;av_dict_free(&opts);int sent=0;int64_t base=0;while(sent<count&&av_read_frame(in,p)>=0){if(p->stream_index==v){if(!sent)base=p->dts;p->pts-=base;p->dts-=base;av_packet_rescale_ts(p,is->time_base,os->time_base);p->stream_index=0;p->pos=-1;if(av_interleaved_write_frame(out,p)<0)return 8;sent++;}av_packet_unref(p);}if(av_write_trailer(out)<0)return 9;uint8_t*bytes=NULL;int n=avio_close_dyn_buf(out->pb,&bytes);out->pb=NULL;FILE*f=fopen(argv[4],"wb");if(!f||fwrite(bytes,1,n,f)!=n)return 10;fclose(f);av_free(bytes);avformat_free_context(out);avformat_close_input(&in);av_packet_free(&p);printf("{\"microseconds\":%lld,\"packets\":%d,\"outputBytes\":%d,\"libavformatVersion\":%u}\n",(long long)(av_gettime_relative()-begin),sent,n,avformat_version());return sent==count?0:11;}
